package cz.lollywood.falloutak;

import com.google.gson.Gson;
import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import com.google.gson.JsonParser;

import java.io.InputStream;
import java.io.InputStreamReader;
import java.nio.charset.StandardCharsets;
import java.util.*;

/**
 * Research (part 8, `08-RESEARCH.md` §3, RULED in rounds 1-3, Marek 11-21; the cards and their numbers [mine, EXAMPLE], generated by
 * LollyWood-Lore `_tools/fallout_catalogue.py` into {@code data/research.json}). Marek's brief (11-13): *"other than just scientists
 * that have high skill level and do science for long time, you need inspiration (getting hand on something related to the research,
 * that helps narrow it down - a bit like research projects in Stellaris), you need to do experiments and finally you need to create
 * and test the prototype."*
 * <ul>
 * <li>A CARD a researched way: P = 100 × T² × R points, the gate (the science at 25 / 50 / 100 / 150 by the tier).</li>
 * <li>The SHARES of P: a find up to 50 % (the GM's; Reverse Engineer's working item taken apart 50 % and a free inspiration), the
 * card's achievement 20 % (PRE-PREPARED as Civ6's Eurekas, round 4: a deed near the invention, counted here, or the GM's for a deed
 * in the world; {@link Ach}), an inspiration 10 % (the GM's, or the lead's
 * weekly roll of Intelligence × 3 %), experiments 2 × 10 % (no roll, expensive: Electronics and Machinery of the tier), related
 * research up to 25 % (5 % a finished card of a shared line; a find, an achievement or an experiment counts at half for the line's
 * running projects). <b>No theory floor</b> (round 2: *"it should be possible to completely cut away the theory by getting only the
 * interactive parts"*).</li>
 * <li>THEORY for the rest: each researcher the science ÷ the gate points an hour (at most 4), up to 3, in a laboratory of the card's
 * tier ({@link Production} runs it as a job).</li>
 * <li>The PROTOTYPE at 100 % (90 % with Prototype): one run of the way in its own building, twice its hours, BUILT BY THE WAY'S OWN CREW
 * LED BY A RESEARCHER (round 4, Marek 11-21: *"it should be build together with the crew. That makes the most sense."*: the lead takes
 * no slot, works too if he has the way's skill, and his science is the test's); the TEST a d100 at
 * 50 % + (skill − gate), +10 % a failed test before, a 100 always fails. Passed: the way is the base's, 100 × T × R XP to each
 * researcher (06b). Failed: the prototype works, one rarity lower; at rarity 1 the GM rules it (round 2: *"I would rule each on case
 * by case basis when it happens..."*).</li>
 * <li>The perks and traits in their RULED forms (round 2, *"yes, that sounds a lot better!"*; round 3, *"yes, fine"*): Absent-Minded
 * Genius (inspirations 20 %, the weekly roll × 1.5), Tinkerer (a third experiment, prototypes −25 % time), Lab Rat (experiments 15 %
 * each, half the apparatus), Eureka (once a project the inspiration at will, worth 10 % more), Prototype (the prototype at 90 %, its
 * first test passes), Data Miner and Reverse Engineer (finds, the GM's).</li>
 * </ul>
 */
final class Research {
    private Research() {}

    // ------------------------------------------------------------------ the data
    /**
     * A card's achievement, pre-prepared (round 4, Marek 11-21, verbatim: *"I think these could pre-prepared. Like in Civ6."* ·
     * *"The "use recipe XX times" kind should be rarer one in this case."* · *"most should work with different type."*). Kinds:
     * {@code made} (units of the type and tier made in the base), {@code recipe} (runs of any of the ways), {@code assembled} (items
     * assembled for going out from parts of the type), {@code building} (that many of the kind at the tier or better; "*" any built
     * beyond the shelter's rooms), {@code stored} (that many in the store at once), {@code condition} (a building of the kind at or
     * below the %), {@code worn} (items of the type worn out in the base's work), {@code cards} (research cards done), {@code gm}
     * (a deed in the world: the GM credits it).
     */
    static final class Ach {
        String kind = "made", type = "", building = "", part = "", text = "", model = "";
        int count = 1, tier = 1;
        double value;
        List<String> recipes = new ArrayList<>();
        boolean auto = true;

        boolean counted() { return !"gm".equals(kind); }
    }

    static final class Apparatus { int electronics = 1, machinery = 1; }

    static final class Card {
        String id = "", name = "", science = "", better = "";
        int tier = 1, rarity = 1, points = 100, gate = 25, lab = 1;
        List<String> recipes = new ArrayList<>(), lines = new ArrayList<>(), needs = new ArrayList<>();
        /** What the tree found (round 4): what must be found, a building no way builds yet. */
        List<String> notes = new ArrayList<>();
        Ach achievement;
        Apparatus experiment = new Apparatus();
        boolean parked;
        /** Round 5 (Marek 11-21): the first way to a TTR or a building's tier: a laboratory two tiers below may research it. */
        boolean basic;

        Production.Recipe target() { return recipes.isEmpty() ? null : Production.RECIPES.get(recipes.get(0)); }
    }

    static final class Rules {
        double find = 50, achievement = 20, inspiration = 10, experiment = 10, related_each = 5, related = 25, theory_max = 4,
                test = 50, test_step = 10, weekly_int = 3;
        int experiments = 2, researchers = 3;
    }

    /** A project's state, kept with the production (saved). */
    static final class Project {
        /** "" = not started, "theory", "done". */
        String status = "";
        /** The shares in % of P: a find, the achievement, the inspiration, the experiments' sum, the related half shares. */
        double find, achievement, inspiration, experiments, related;
        /** Theory points done; this week's theory hours (the weekly roll). */
        double theory, weekHours;
        int experimentsDone, failures;
        /** The achievement's count so far (units made, runs, items assembled). */
        int achieved;
        boolean eureka;
        /** Who worked on it (worker ids): the XP on the passed test. */
        List<String> researchers = new ArrayList<>();
    }

    /** A failed prototype at rarity 1 for the GM to rule (round 2). */
    static final class Pending {
        String card = "", text = "";
        List<Production.Ttr> makes = new ArrayList<>();
        Production.Builds builds;
    }

    static final Map<String, Card> CARDS = new LinkedHashMap<>();
    static Rules RULES = new Rules();
    /** The research jobs as recipes the buildings run: {@code research|<card>|theory|experiment|prototype}. */
    static final Map<String, Production.Recipe> JOBS = new LinkedHashMap<>();

    static {
        try (InputStream in = Research.class.getResourceAsStream("/data/research.json")) {
            if (in != null) {
                JsonObject o = JsonParser.parseReader(new InputStreamReader(in, StandardCharsets.UTF_8)).getAsJsonObject();
                Gson g = new Gson();
                if (o.has("rules")) RULES = g.fromJson(o.get("rules"), Rules.class);
                for (JsonElement e : o.getAsJsonArray("rows")) { Card c = g.fromJson(e, Card.class); CARDS.put(c.id, c); }
            }
        } catch (Exception e) {
            throw new IllegalStateException("data/research.json: " + e.getMessage(), e);
        }
        for (Card c : CARDS.values()) {
            Production.Recipe t = c.target();
            if (t == null) continue;
            Production.Recipe th = job(c, "theory", "Theory: " + c.name, "Laboratory", c.lab, 0);
            th.note = "the science ÷ " + c.gate + " points an hour each (at most " + Math.round(RULES.theory_max) + "), until the theory is done";
            Production.Recipe ex = job(c, "experiment", "Experiment: " + c.name, "Laboratory", c.lab, Math.max(1, t.hours));
            ex.inputs.add(ttr("Electronics", c.tier, c.experiment.electronics));
            ex.inputs.add(ttr("Machinery", c.tier, c.experiment.machinery));
            ex.note = "the apparatus is used up; no roll, it gives its share (Lab Rat: 15 % and half the apparatus)";
            Production.Recipe pt = job(c, "prototype", "Prototype: " + c.name, t.building, t.tier, Math.max(1, 2 * t.hours));
            pt.skill = t.skill;   // round 4: the way's own crew builds it, a researcher leads (Production.Job.lead)
            pt.min = t.min;
            pt.inputs.addAll(t.inputs);
            pt.makes.addAll(t.makes);
            pt.builds = t.builds;
            pt.note = "twice the way's hours (Tinkerer −25 %), by a crew of " + t.skill + " " + t.min + " led by a researcher (" + c.science + " "
                    + c.gate + "), then the test";
        }
    }

    private static Production.Recipe job(Card c, String what, String name, String building, int tier, double hours) {
        Production.Recipe r = new Production.Recipe();
        r.id = "research|" + c.id + "|" + what;
        r.name = name;
        r.building = building;
        r.tier = Math.max(1, Math.min(4, tier));
        r.skill = c.science;
        r.min = c.gate;
        r.hours = hours;
        JOBS.put(r.id, r);
        return r;
    }

    private static Production.Ttr ttr(String type, int tier, int n) {
        Production.Ttr t = new Production.Ttr();
        t.type = type;
        t.tier = tier;
        t.count = Math.max(0, n);
        return t;
    }

    static boolean isJob(Production.Recipe r) { return r != null && r.id.startsWith("research|"); }

    static Card cardOf(Production.Recipe r) { return isJob(r) ? CARDS.get(r.id.split("\\|")[1]) : null; }

    static String what(Production.Recipe r) { return isJob(r) ? r.id.substring(r.id.lastIndexOf('|') + 1) : ""; }

    static boolean theory(Production.Recipe r) { return isJob(r) && r.id.endsWith("|theory"); }

    static boolean experiment(Production.Recipe r) { return isJob(r) && r.id.endsWith("|experiment"); }

    static boolean prototype(Production.Recipe r) { return isJob(r) && r.id.endsWith("|prototype"); }

    static Production.Recipe jobFor(Card c, String what) { return JOBS.get("research|" + c.id + "|" + what); }

    // ------------------------------------------------------------------ the shares
    static Project project(Production pr, Card c) { return pr.research.computeIfAbsent(c.id, k -> new Project()); }

    static boolean done(Production pr, Card c) { Project p = pr.research.get(c.id); return p != null && "done".equals(p.status); }

    /** The cards it needs are done. */
    static boolean open(Production pr, Card c) {
        for (String n : c.needs) { Card d = CARDS.get(n); if (d != null && !done(pr, d)) return false; }
        return true;
    }

    /** Does anyone of these people (the project's researchers, a run's crew) have this perk or trait. */
    static boolean perk(Project p, Collection<Production.Worker> people, String name) {
        for (Production.Worker w : people) if (w != null && w.perk(name)) return true;
        return false;
    }

    /** The project's researchers among the workforce (those who worked on it). */
    static List<Production.Worker> researchers(Project p, Production.Workforce wf) {
        List<Production.Worker> l = new ArrayList<>();
        if (p == null || wf == null) return l;
        for (Production.Worker w : wf.all()) if (p.researchers.contains(w.id())) l.add(w);
        return l;
    }

    static double related(Production pr, Card c, Project p) {
        int n = 0;
        for (Card d : CARDS.values()) if (d != c && done(pr, d) && shares(c, d)) n++;
        return Math.min(RULES.related, n * RULES.related_each + (p == null ? 0 : p.related));
    }

    static boolean shares(Card a, Card b) {
        for (String l : a.lines) if (b.lines.contains(l)) return true;
        return false;
    }

    /** The shares but theory, in % of P. */
    static double shares(Production pr, Card c, Project p) {
        if (p == null) return related(pr, c, null);
        return Math.min(RULES.find, p.find) + Math.min(RULES.achievement, p.achievement) + p.inspiration + p.experiments + related(pr, c, p);
    }

    /** The progress in % (shares + theory), at most 100. */
    static double progress(Production pr, Card c) {
        Project p = pr.research.get(c.id);
        return Math.min(100, shares(pr, c, p) + (p == null ? 0 : 100 * p.theory / Math.max(1, c.points)));
    }

    /** The theory points still needed (0 = theory done). */
    static double theoryLeft(Production pr, Card c) {
        Project p = pr.research.get(c.id);
        double need = c.points * Math.max(0, 1 - shares(pr, c, p) / 100);
        return Math.max(0, need - (p == null ? 0 : p.theory));
    }

    /** At 100 %, or 90 % when a researcher has Prototype (round 3: *"yes, fine"*). */
    static boolean ready(Production pr, Card c, Production.Workforce wf) {
        double need = perk(null, researchers(pr.research.get(c.id), wf), "Prototype") ? 90 : 100;
        return progress(pr, c) >= need - 1e-9;
    }

    /** How many experiments the project may have: 2, Tinkerer 3. */
    static int maxExperiments(Project p, Production.Workforce wf, Collection<Production.Worker> crew) {
        List<Production.Worker> l = new ArrayList<>(researchers(p, wf));
        if (crew != null) l.addAll(crew);
        return RULES.experiments + (perk(p, l, "Tinkerer") ? 1 : 0);
    }

    /** An inspiration's worth: 10 %, Absent-Minded Genius 20 %. */
    static double inspirationWorth(Collection<Production.Worker> people) {
        return RULES.inspiration * (perk(null, people, "Absent-Minded Genius") ? 2 : 1);
    }

    /** A share credited to a project also counts at half for the running projects of its lines (round 2: related research). */
    private static void spread(Production pr, Card c, double share) {
        for (Card d : CARDS.values()) {
            if (d == c || !shares(c, d)) continue;
            Project q = pr.research.get(d.id);
            if (q != null && "theory".equals(q.status)) q.related += share / 2;
        }
    }

    // ------------------------------------------------------------------ the GM's credits and Eureka
    /** A find (the GM names the share, at most 50 %; Reverse Engineer's working item taken apart: 50 % and a free inspiration). */
    static String find(Production pr, Card c, double share, boolean reverse, Production.Workforce wf) {
        Project p = project(pr, c);
        double before = Math.min(RULES.find, p.find);
        p.find = Math.min(RULES.find, p.find + (reverse ? RULES.find : Math.max(0, share)));
        double got = Math.min(RULES.find, p.find) - before;
        spread(pr, c, got);
        String s = c.name + ": a find +" + Math.round(got) + " %";
        if (reverse && p.inspiration <= 0) { p.inspiration = inspirationWorth(researchers(p, wf)); s += ", and the inspiration +" + Math.round(p.inspiration) + " % (Reverse Engineer)"; }
        return s + " → " + Math.round(progress(pr, c)) + " %";
    }

    static String achievement(Production pr, Card c) {
        Project p = project(pr, c);
        if (p.achievement >= RULES.achievement) return "! " + c.name + " has its achievement already";
        p.achievement = RULES.achievement;
        spread(pr, c, RULES.achievement);
        return c.name + ": its achievement +" + Math.round(RULES.achievement) + " % → " + Math.round(progress(pr, c)) + " %";
    }

    /** The cards whose achievement of this kind is still open (not done, not parked, not met). */
    private static List<Card> waiting(Production pr, String kind) {
        List<Card> l = new ArrayList<>();
        for (Card c : CARDS.values()) {
            if (c.parked || c.achievement == null || done(pr, c) || !kind.equals(c.achievement.kind)) continue;
            Project p = pr.research.get(c.id);
            if (p != null && p.achievement >= RULES.achievement) continue;
            l.add(c);
        }
        return l;
    }

    private static void met(Production pr, Card c, List<String> out) {
        Project p = project(pr, c);
        p.achievement = RULES.achievement;
        spread(pr, c, RULES.achievement);
        out.add("Research: " + c.name + ": its achievement met (" + c.achievement.text + ") +" + Math.round(RULES.achievement) + " %");
    }

    /** An event that counts: the achievement's count grows by n, met at its count. */
    private static void count(Production pr, Card c, int n, List<String> out) {
        if (n <= 0) return;
        Project p = project(pr, c);
        p.achieved += n;
        if (p.achieved >= c.achievement.count) met(pr, c, out);
    }

    /** The achievement's count now: what was counted, or the state it asks about. */
    static int achievedNow(Production pr, Card c, Base base) {
        Ach a = c.achievement;
        if (a == null) return 0;
        Project p = pr.research.get(c.id);
        switch (a.kind) {
            case "building": {
                int n = 0;
                for (Production.Building b : pr.buildings) {
                    if (b.site || b.tier < a.tier) continue;
                    if ("*".equals(a.building) ? !pr.shelterRoom(b) : a.building.equals(b.kind)) n++;
                }
                return n;
            }
            case "stored": {
                int n = 0;
                if (base != null) for (int t = a.tier; t <= 4; t++) n += base.count(a.type, t, 0);
                return n;
            }
            case "condition": {
                for (Production.Building b : pr.buildings) if (a.building.equals(b.kind) && b.condition <= a.value + 1e-9) return 1;
                return 0;
            }
            case "worn": return base == null ? 0 : base.wornOut(a.type);
            case "cards": {
                int n = 0;
                for (Card d : CARDS.values()) if (d != c && done(pr, d)) n++;
                return n;
            }
            default: return p == null ? 0 : p.achieved;
        }
    }

    /** The achievement as a line: what it asks, how it is met, how far (round 4). */
    static String achievementLine(Production pr, Card c, Base base) {
        Ach a = c.achievement;
        if (a == null) return "The achievement: the GM credits it";
        Project p = pr.research.get(c.id);
        boolean met = p != null && p.achievement > 0;
        if (!a.counted()) return "The achievement (the GM credits it): " + a.text + (met ? " (met)" : "");
        int need = "condition".equals(a.kind) ? 1 : a.count;
        return "The achievement (counted): " + a.text + (met ? " (met)" : ", " + Math.min(need, achievedNow(pr, c, base)) + " of " + need);
    }

    /** The state kinds (round 4): a building built, a store's stock, a room's condition, tools worn out, cards done. */
    static void check(Production pr, Base base, List<String> out) {
        for (String kind : List.of("building", "stored", "condition", "worn", "cards"))
            for (Card c : waiting(pr, kind)) {
                int need = "condition".equals(kind) ? 1 : c.achievement.count;
                if (achievedNow(pr, c, base) >= need) met(pr, c, out);
            }
    }

    /** A run of a way is done (the recipe kind: a way used N times, round 4's rare kind). */
    static void ran(Production pr, String recipeId, List<String> out) {
        for (Card c : waiting(pr, "recipe")) if (c.achievement.recipes.contains(recipeId)) count(pr, c, 1, out);
    }

    /** Items assembled for going out (the assembled kind): those whose parts include the achievement's part type. */
    static void assembled(Production pr, Production.Design d, int items, List<String> out) {
        if (d == null || items <= 0) return;
        for (Card c : waiting(pr, "assembled")) {
            boolean uses = false;
            for (Production.Part p : d.parts) if (p.type.equals(c.achievement.part)) uses = true;
            if (uses) count(pr, c, items, out);
        }
    }

    /** The cards this one opens the way to (the tree, round 4). */
    static List<Card> opens(Card c) {
        List<Card> l = new ArrayList<>();
        for (Card d : CARDS.values()) if (!d.parked && d.needs.contains(c.id)) l.add(d);
        return l;
    }

    /** Who leads a prototype: the project's best free researcher, else the best free worker at the card's science and gate. */
    static Production.Worker lead(Production pr, Card c, Production.Workforce wf) {
        Project p = pr.research.get(c.id);
        Production.Worker best = null;
        for (int pass = 0; pass < 2 && best == null; pass++)
            for (Production.Worker w : wf.all()) {
                if (pr.busyAt(w.id()) != null || w.skill(c.science) < c.gate) continue;
                if (pass == 0 && (p == null || !p.researchers.contains(w.id()))) continue;
                if (best == null || w.skill(c.science) > best.skill(c.science)) best = w;
            }
        return best;
    }

    static String inspiration(Production pr, Card c, Production.Workforce wf) {
        Project p = project(pr, c);
        if (p.inspiration > 0) return "! " + c.name + " has its inspiration already";
        p.inspiration = inspirationWorth(researchers(p, wf));
        return c.name + ": an inspiration +" + Math.round(p.inspiration) + " % → " + Math.round(progress(pr, c)) + " %";
    }

    /** Eureka (round 3): once a project, the inspiration at will, worth 10 % more. */
    static String eureka(Production pr, Card c, Production.Workforce wf) {
        Project p = project(pr, c);
        List<Production.Worker> rs = researchers(p, wf);
        if (!perk(p, rs, "Eureka")) return "! nobody who works on " + c.name + " has Eureka";
        if (p.eureka) return "! Eureka was used on " + c.name + " already";
        if (p.inspiration > 0) return "! " + c.name + " has its inspiration already";
        p.eureka = true;
        p.inspiration = inspirationWorth(rs) + RULES.inspiration;
        return c.name + ": Eureka! the inspiration +" + Math.round(p.inspiration) + " % → " + Math.round(progress(pr, c)) + " %";
    }

    // ------------------------------------------------------------------ the clock (Production calls these)
    /** Units made in the base: they count for the achievements of the made kind that name them. */
    static void made(Production pr, String type, int tier, int n, List<String> out) {
        if (n <= 0) return;
        for (Card c : waiting(pr, "made")) if (c.achievement.type.equals(type) && c.achievement.tier == tier) count(pr, c, n, out);
    }

    /** An hour of theory: the points (the crew's science ÷ the gate, at most 4 each, already summed by the caller × the room's efficiency). */
    static void theoryHour(Production pr, Production.Building b, Production.Recipe r, List<Production.Worker> crew, double points, double dt,
                           Production.Workforce wf, List<String> out) {
        Card c = cardOf(r);
        if (c == null) return;
        Project p = project(pr, c);
        p.status = "theory";
        if (crew.isEmpty() || points <= 0) { b.job.waiting = "no researchers"; return; }
        for (Production.Worker w : crew) if (!p.researchers.contains(w.id())) p.researchers.add(w.id());
        p.weekHours += dt;
        double left = theoryLeft(pr, c);
        p.theory += Math.min(points, left);
        if (theoryLeft(pr, c) <= 1e-9) {
            out.add(b.name + ": " + c.name + ": the theory is done (" + Math.round(progress(pr, c)) + " %): the prototype next");
            pr.end(b, wf);
        }
    }

    /** The lead's weekly roll for the inspiration (Intelligence × 3 %; Absent-Minded Genius × 1.5), for the projects in theory this week. */
    static void weekRolls(Production pr, Map<String, Production.Worker> byId, List<String> out) {
        for (Production.Building b : pr.buildings) {
            Production.Recipe r = b.job == null ? null : Production.recipe(b.job.recipe);
            if (!theory(r)) continue;
            Card c = cardOf(r);
            Project p = pr.research.get(c.id);
            if (p == null || p.weekHours <= 0) continue;
            p.weekHours = 0;
            if (p.inspiration > 0) continue;
            List<Production.Worker> crew = new ArrayList<>();
            for (String id : b.crew) if (byId.get(id) != null) crew.add(byId.get(id));
            Production.Worker lead = null;
            for (Production.Worker w : crew) if (w.sheet() != null && (lead == null || w.sheet().attr(cz.lollywood.falloutak.Rules.I, false) > lead.sheet().attr(cz.lollywood.falloutak.Rules.I, false))) lead = w;
            if (lead == null) continue;
            double chance = lead.sheet().attr(cz.lollywood.falloutak.Rules.I, false) * RULES.weekly_int * (lead.perk("Absent-Minded Genius") ? 1.5 : 1);
            int roll = 1 + pr.rng().nextInt(100);
            if (roll <= chance) {
                p.inspiration = inspirationWorth(crew);
                out.add("Research: " + c.name + ": " + lead.label() + "'s inspiration (rolled " + roll + " of " + Math.round(chance) + " %) +"
                        + Math.round(p.inspiration) + " % → " + Math.round(progress(pr, c)) + " %");
            }
        }
    }

    /** The work an experiment or a prototype run needs (the prototype: Tinkerer −25 %). */
    static double need(Production.Recipe r, List<Production.Worker> crew) {
        return prototype(r) && perk(null, crew, "Tinkerer") ? r.hours * 0.75 : r.hours;
    }

    /** Lab Rat: half the experiment's apparatus (rounded up). */
    static int count(Production.Recipe r, Production.Ttr i, List<Production.Worker> crew) {
        return experiment(r) && perk(null, crew, "Lab Rat") ? (i.count + 1) / 2 : i.count;
    }

    /** An experiment or a prototype run is done. */
    static void finish(Production pr, Production.Building b, Production.Recipe r, Base base, Production.Workforce wf, List<Production.Worker> crew, List<String> out) {
        Card c = cardOf(r);
        Project p = project(pr, c);
        if (experiment(r)) for (Production.Worker w : crew) if (!p.researchers.contains(w.id())) p.researchers.add(w.id());
        if (prototype(r) && !b.job.lead.isEmpty() && !p.researchers.contains(b.job.lead)) p.researchers.add(b.job.lead);   // the crew: work XP
        if (experiment(r)) {
            double share = perk(p, crew, "Lab Rat") ? 1.5 * RULES.experiment : RULES.experiment;
            p.experimentsDone++;
            p.experiments += share;
            spread(pr, c, share);
            out.add(b.name + ": " + r.name + " done (" + p.experimentsDone + " of " + maxExperiments(p, wf, crew) + ") +" + Math.round(share) + " % → "
                    + Math.round(progress(pr, c)) + " %");
            pr.end(b, wf);
            return;
        }
        // the prototype's test (round 1: "Is the prototype test fine as described? - yes."): the best science of its builders (the lead's)
        double skill = 0;
        for (Production.Worker w : crew) skill = Math.max(skill, w.skill(c.science));
        double chance = RULES.test + (skill - c.gate) + RULES.test_step * p.failures;
        int roll = 1 + pr.rng().nextInt(100);
        boolean free = p.failures == 0 && perk(p, crew, "Prototype");
        boolean pass = free || (roll < 100 && roll <= chance);
        String test = free ? "its first test passes (Prototype)" : "the test: rolled " + roll + " of " + Math.round(Math.min(99, chance)) + " %";
        int rarity = Math.max(1, b.job.madeRarity);
        if (pass) {
            p.status = "done";
            pr.known.addAll(c.recipes);
            StringJoiner made = new StringJoiner(", ");
            give(pr, base, r.makes, r.builds, r.makes.isEmpty() ? 0 : r.makes.get(0).tier, rarity, made);
            long xp = cz.lollywood.falloutak.Rules.researchXp(c.tier, c.rarity);
            for (String id : p.researchers) wf.award(id, xp, "research: " + c.name);
            out.add(b.name + ": " + r.name + ": " + test + ": PASSED. The base knows " + c.name + " now (" + c.better + "); "
                    + (made.length() == 0 ? "" : "the prototype: " + made + "; ") + xp + " XP to each of " + p.researchers.size()
                    + (p.researchers.size() == 1 ? " researcher" : " researchers"));
        } else {
            p.failures++;
            if (rarity > 1) {
                StringJoiner made = new StringJoiner(", ");
                give(pr, base, r.makes, r.builds, 0, rarity - 1, made);
                out.add(b.name + ": " + r.name + ": " + test + ": FAILED. The prototype works, one rarity lower (" + made + "); a new prototype and test are needed");
            } else {
                Pending pd = new Pending();
                pd.card = c.id;
                pd.makes.addAll(r.makes);
                pd.builds = r.builds;
                pd.text = r.name + " (" + Production.makesText(r) + ")";
                pr.pending.add(pd);
                out.add(b.name + ": " + r.name + ": " + test + ": FAILED at rarity 1: the GM rules what the prototype comes out as (GM: research); a new prototype and test are needed");
            }
        }
        pr.end(b, wf);
    }

    /** What a prototype gives: its outputs at this rarity (a tier given = the GM's ruling, 0 = their own), or its building. */
    static void give(Production pr, Base base, List<Production.Ttr> makes, Production.Builds builds, int tier, int rarity, StringJoiner made) {
        if (builds != null) {
            Production.Building nb = pr.build(builds.kind, tier > 0 ? tier : builds.tier, builds.kind);
            made.add("a new " + nb.label());
        }
        for (Production.Ttr m : makes) {
            int t = tier > 0 ? tier : m.tier;
            base.addUnits(m.type, t, Math.max(1, Math.min(4, rarity)), m.count);
            made.add(m.count + " " + m.type + " " + cz.lollywood.falloutak.Rules.roman(t) + " R" + Math.max(1, Math.min(4, rarity)));
        }
    }

    /** The GM rules a failed rarity-1 prototype (round 2): it comes out at this tier and rarity, or nothing. */
    static String rule(Production pr, Base base, Pending pd, int tier, int rarity, boolean nothing) {
        pr.pending.remove(pd);
        if (nothing) return pd.text + ": nothing comes of it";
        StringJoiner made = new StringJoiner(", ");
        give(pr, base, pd.makes, pd.builds, tier, rarity, made);
        return pd.text + ": comes out as " + made;
    }

    /** One line of a card's progress by source. */
    static String breakdown(Production pr, Card c) {
        Project p = pr.research.get(c.id);
        StringJoiner j = new StringJoiner(" · ");
        if (p != null) {
            if (p.find > 0) j.add("find " + Math.round(Math.min(RULES.find, p.find)) + " %");
            if (p.achievement > 0) j.add("achievement " + Math.round(p.achievement) + " %");
            if (p.inspiration > 0) j.add("inspiration " + Math.round(p.inspiration) + " %" + (p.eureka ? " (Eureka)" : ""));
            if (p.experimentsDone > 0) j.add(p.experimentsDone + (p.experimentsDone == 1 ? " experiment " : " experiments ") + Math.round(p.experiments) + " %");
            if (p.theory > 0) j.add("theory " + Math.round(100 * p.theory / Math.max(1, c.points)) + " %");
        }
        double rel = related(pr, c, p);
        if (rel > 0) j.add("related " + Math.round(rel) + " %");
        return j.length() == 0 ? "nothing yet" : j.toString();
    }

    /** The card's state in a word. */
    static String state(Production pr, Card c, Production.Workforce wf) {
        if (done(pr, c)) return "done";
        if (!open(pr, c)) return "needs " + needsText(c);
        if (ready(pr, c, wf)) return "the prototype";
        Project p = pr.research.get(c.id);
        return p != null && "theory".equals(p.status) ? "in theory" : "open";
    }

    static String needsText(Card c) {
        StringJoiner j = new StringJoiner(", ");
        for (String n : c.needs) { Card d = CARDS.get(n); j.add(d == null ? n : d.name); }
        return j.toString();
    }
}
